import json
import time
import mlflow
from mlflow.entities import SpanType
from datetime import date, datetime
from dataclasses import dataclass, field, asdict
from typing import List, Optional, Dict, Any
from openai import OpenAI
from databricks.sdk import WorkspaceClient


# --- Data Models ---

@dataclass
class Candidate:
    corpus_id: str
    question: str
    score: float
    status: str
    next_review_date: date
    parameterized_sql: str
    answer_template: str
    parameters: List[str]


@dataclass
class RouterResult:
    answer: str
    badge: str
    confidence: float
    lane: str
    provenance: Dict[str, Any] = field(default_factory=dict)
    suggestion: Optional[str] = None

    def to_dict(self) -> dict:
        return asdict(self)


# --- Helper functions ---

def _parse_date(val) -> date:
    if val is None:
        return date.today()
    if isinstance(val, date):
        return val
    try:
        return date.fromisoformat(str(val)[:10])
    except (ValueError, TypeError):
        return date.today()


def _call_llm(prompt: str, temperature: float = 0.0, max_tokens: int = 150) -> str:
    client = OpenAI(
        api_key=os.environ.get("DATABRICKS_TOKEN", ""),
        base_url=f"{os.environ.get('DATABRICKS_HOST', '')}/serving-endpoints"
    )
    try:
        response = client.chat.completions.create(
            model=JUDGE_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=temperature,
            max_tokens=max_tokens
        )
        return response.choices[0].message.content.strip()
    except Exception as e:
        return f'{{"score": 50, "reasoning": "LLM error: {e}"}}'


# --- Step 1: Retrieve ---

def retrieve(prompt: str) -> List[Candidate]:
    w = WorkspaceClient()
    try:
        results = w.vector_search_indexes.query_index(
            index_name=VS_INDEX,
            columns=[
                "id", "question", "parameterized_sql", "answer_template",
                "parameters", "status", "certified_by", "certified_date",
                "next_review_date"
            ],
            query_text=prompt,
            num_results=VS_TOP_K,
            filters_json='{"status NOT": "expired"}'
        )
    except Exception as e:
        return []

    candidates = []
    if results and results.result and results.result.data_array:
        columns = [col.name for col in results.manifest.columns]
        for row in results.result.data_array:
            row_dict = dict(zip(columns, row))
            candidates.append(Candidate(
                corpus_id=row_dict.get("id", ""),
                question=row_dict.get("question", ""),
                score=float(row_dict.get("score", 0.0)),
                status=row_dict.get("status", ""),
                next_review_date=_parse_date(row_dict.get("next_review_date")),
                parameterized_sql=row_dict.get("parameterized_sql", ""),
                answer_template=row_dict.get("answer_template", ""),
                parameters=row_dict.get("parameters", []) or [],
            ))
    return candidates


# --- Step 3: Rerank ---

def rerank_and_calibrate(prompt: str, candidate: Candidate) -> float:
    judge_prompt = f"""You are an intent matching judge. Compare these two questions and score how similar their intent is.

User question: "{prompt}"
Certified question: "{candidate.question}"

Score the intent similarity from 0 to 100 where:
- 100 = identical intent (same question, possibly different wording)
- 75-99 = very similar intent (asking about the same metric/topic with minor differences)
- 50-74 = related but different specific ask
- 0-49 = different intent entirely

Respond with ONLY a JSON object: {{"score": <number>, "reasoning": "<brief explanation>"}}"""

    content = _call_llm(judge_prompt)
    
    try:
        if content.startswith("```"):
            content = content.split("```")[1]
            if content.startswith("json"):
                content = content[4:]
        result = json.loads(content)
        raw_score = float(result.get("score", 0))
    except Exception:
        raw_score = candidate.score * 100

    normalized = min(max(raw_score / 100.0, 0.0), 1.0)
    calibrated = normalized * SHRINK_FACTOR
    return calibrated


# --- Step 4: Staleness Check ---

def staleness_check(confidence: float, candidate: Candidate) -> float:
    is_stale = candidate.next_review_date < date.today()
    if is_stale:
        confidence = min(confidence, CONFIDENCE_THRESHOLD - 0.01)
    return confidence


# --- Step 5: Gate Decision ---

def gate_decision(confidence: float, candidate: Candidate) -> str:
    if confidence >= CONFIDENCE_THRESHOLD and candidate.status == "certified":
        return "certified"
    return "analytical"


# --- Main Router Function (simplified for eval — no SQL execution or Genie call) ---

def run_router(prompt: str) -> Dict[str, Any]:
    """
    Simplified router for evaluation. Runs the confidence gate logic
    but skips actual SQL execution and Genie calls (we only need routing decision).
    """
    start_time = time.time()

    # Step 1: Retrieve
    candidates = retrieve(prompt)

    # Step 2: Short-circuit
    if not candidates:
        latency_ms = int((time.time() - start_time) * 1000)
        return {
            "lane": "analytical",
            "badge": "NOT YET APPROVED",
            "confidence": 0.0,
            "corpus_id": None,
            "top_candidate_question": None,
            "vs_score": 0.0,
            "latency_ms": latency_ms,
            "short_circuit": True,
        }

    # Step 3: Rerank/Calibrate
    top_candidate = candidates[0]
    confidence = rerank_and_calibrate(prompt, top_candidate)

    # Step 4: Staleness Check
    confidence = staleness_check(confidence, top_candidate)

    # Step 5: Gate Decision
    lane = gate_decision(confidence, top_candidate)
    badge = "HUMAN APPROVED" if lane == "certified" else "NOT YET APPROVED"

    latency_ms = int((time.time() - start_time) * 1000)

    return {
        "lane": lane,
        "badge": badge,
        "confidence": confidence,
        "corpus_id": top_candidate.corpus_id,
        "top_candidate_question": top_candidate.question,
        "vs_score": top_candidate.score,
        "latency_ms": latency_ms,
        "short_circuit": False,
    }

